const state = flow.get('ros2SearchDashboard');
if (!state) {
    return { topic: 'dashboard/init', payload: '' };
}
return { topic: 'dashboard/watchdog', payload: { now: Date.now() } };

function initialState() {
    return {
        px4: { status_state: 'UNKNOWN', mqtt_connected: false, arming_state_name: 'UNKNOWN', arming_state: null, armed: null, landed: null, status_age_ms: null, failsafe: null, gcs_connection_lost: null, pre_flight_checks_pass: null, plan_management_message: 'Waiting for PX4 status' },
        planner: { status_state: 'UNKNOWN', plan_management_allowed: false, arming_state_name: 'UNKNOWN', status_age_ms: null, active_working_plan: '', last_error: '', message: 'Waiting for live planner status' },
        plans: { plans: [], default_manual_plan: '', active_working_plan: '', available: false, message: 'Waiting for manual-plan list' },
        selectedPlan: '',
        safety: { allowed: false, retained: false, bridgeOffline: false, lastLiveAt: 0, ageMs: null, liveStatus: null },
        pending: null,
        lastResponse: null,
        notice: { level: 'info', text: 'Waiting for search_bridge...', at: Date.now() }
    };
}

function parsePayload(value) {
    if (typeof value === 'string') {
        try { return JSON.parse(value); } catch (error) { return null; }
    }
    return value && typeof value === 'object' ? value : null;
}

let state = flow.get('ros2SearchDashboard') || initialState();
const now = Date.now();
const topic = msg.topic || '';
const payload = parsePayload(msg.payload);

if (topic === 'dashboard/init') {
    state.notice = { level: 'info', text: 'Waiting for search_bridge MQTT state...', at: now };
} else if (topic === 'dashboard/watchdog') {
    if (state.safety.liveStatus && now - state.safety.lastLiveAt > 3000) {
        state.safety.allowed = false;
        state.safety.ageMs = now - state.safety.lastLiveAt;
        state.notice = { level: 'warning', text: 'No live planner status update; plan controls disabled', at: now };
    }
    if (state.pending && now - state.pending.sentAt > 10000) {
        state.pending = null;
        state.notice = { level: 'warning', text: 'No planner response received. Outcome is unknown; inspect the active plan before retrying reset.', at: now };
    }
} else if (topic === 'dashboard/local' && payload) {
    if (payload.kind === 'selectedPlan') {
        state.selectedPlan = payload.planName || '';
    } else if (payload.kind === 'pending') {
        state.pending = payload.pending || null;
        if (payload.notice) state.notice = payload.notice;
    } else if (payload.kind === 'notice') {
        state.notice = { level: payload.level || 'info', text: payload.text || '', at: now };
    }
} else if (topic.endsWith('/px4/status') && payload) {
    state.px4 = payload;
} else if (topic.endsWith('/planner/plans') && payload) {
    state.plans = payload;
    const planNames = Array.isArray(payload.plans) ? payload.plans : [];
    if (planNames.indexOf(state.selectedPlan) < 0) {
        const defaultPlan = typeof payload.default_manual_plan === 'string' ? payload.default_manual_plan : '';
        state.selectedPlan = planNames.indexOf(defaultPlan) >= 0 ? defaultPlan : (planNames[0] || '');
    }
} else if (topic.endsWith('/planner/status') && payload) {
    state.planner = payload;
    const retained = msg.retain === true;
    if (payload.status_state === 'OFFLINE') {
        state.safety.bridgeOffline = true;
        state.safety.retained = retained;
        state.safety.liveStatus = payload;
        state.safety.lastLiveAt = now;
        state.safety.allowed = false;
    } else if (retained) {
        state.safety.bridgeOffline = false;
        state.safety.retained = true;
        state.safety.liveStatus = null;
        state.safety.lastLiveAt = 0;
        state.safety.allowed = false;
    } else {
        state.safety.bridgeOffline = false;
        state.safety.retained = false;
        state.safety.liveStatus = payload;
        state.safety.lastLiveAt = now;
        state.safety.allowed = payload.status_state === 'DISARMED' && payload.plan_management_allowed === true;
    }
} else if (topic.endsWith('/planner/response') && payload) {
    if (state.pending && payload.request_id === state.pending.requestId) {
        state.lastResponse = payload;
        state.pending = null;
        state.notice = { level: payload.success === true ? 'success' : 'error', text: payload.message || 'Planner command completed', at: now };
        if (payload.success === true && typeof payload.active_working_plan === 'string') {
            state.plans.active_working_plan = payload.active_working_plan;
        }
    }
}

if (state.safety.liveStatus && state.safety.lastLiveAt > 0) {
    state.safety.ageMs = Math.max(0, now - state.safety.lastLiveAt);
    if (state.safety.ageMs > 3000) state.safety.allowed = false;
}
if (state.safety.bridgeOffline) state.safety.allowed = false;

flow.set('ros2SearchDashboard', state);
msg.topic = 'dashboard/state';
msg.payload = state;
return msg;

const event = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const state = flow.get('ros2SearchDashboard');
const local = (level, text) => ({ topic: 'dashboard/local', payload: { kind: 'notice', level, text } });

if (!state) return [null, local('warning', 'Dashboard state is not initialized')];

if (event.action === 'select') {
    const names = state.plans && Array.isArray(state.plans.plans) ? state.plans.plans : [];
    if (typeof event.plan_name !== 'string' || names.indexOf(event.plan_name) < 0) {
        return [null, local('warning', 'Select a manual plan from the bridge-provided list')];
    }
    return [null, { topic: 'dashboard/local', payload: { kind: 'selectedPlan', planName: event.plan_name } }];
}

if (event.action !== 'list' && event.action !== 'reset') return [null, null];
if (!state.safety || state.safety.allowed !== true) {
    return [null, local('warning', 'Command blocked: planner is not currently live and DISARMED')];
}
if (state.pending) {
    return [null, local('warning', 'A planner command is already pending')];
}

const command = event.action === 'reset' ? 'reset_working_plan' : 'list_manual_plans';
const planName = event.plan_name;
if (command === 'reset_working_plan') {
    const names = state.plans && Array.isArray(state.plans.plans) ? state.plans.plans : [];
    const safeName = typeof planName === 'string' && planName.length > 5 && planName.slice(-5) === '.plan' && planName.indexOf('/') < 0 && planName.indexOf('..') < 0 && planName.indexOf(String.fromCharCode(92)) < 0;
    if (!safeName || names.indexOf(planName) < 0) {
        return [null, local('warning', 'Reset blocked: choose a valid manual .plan from the current list')];
    }
}

const now = Date.now();
const requestId = 'nr-' + now.toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const pending = { requestId, command, planName: command === 'reset_working_plan' ? planName : '', sentAt: now };
state.pending = pending;
flow.set('ros2SearchDashboard', state);

const commandMessage = {
    topic: 'search/planner/command',
    qos: 1,
    retain: false,
    payload: JSON.stringify(command === 'reset_working_plan'
        ? { request_id: requestId, command, plan_name: planName }
        : { request_id: requestId, command })
};
const uiMessage = {
    topic: 'dashboard/local',
    payload: { kind: 'pending', pending, notice: { level: 'info', text: 'Sending ' + command + '...', at: now } }
};
return [commandMessage, uiMessage];
